const L={"key": "bundle", "title": "Wedding Speech Template Bundle, Best Man, Maid of Honour, Father of the Bride, Groom Speech, UK, Printable PDF and Editable Word", "desc": "All six wedding speeches in one download, for UK weddings. 30 fill-in templates. Printable PDF (100 pages) plus an editable Word file.\n\nSpeeches included:\n- Best man\n- Maid of honour\n- Father of the bride\n- Groom\n- Mother of the bride\n- Bride (including a version to give together with the groom)\n\nEach speech has its own full section:\n- How to use it, and how long it should be\n- The usual UK running order, and what the speech needs to do\n- A story worksheet\n- How a good speech is built, part by part\n- 5 fill-in templates: classic, funny, heartfelt, short, and one more\n- Opening lines and toasts\n- What to leave out, and wording for remembering someone who isn't here\n- Delivery tips, a final checklist and printable cue cards\n\nShare it with the whole wedding party, so nobody tells the same story twice.\n\nFiles: 1 PDF (A4, also prints on US Letter) and 1 Word file (.docx). This is a digital download. Nothing will be posted.\n\nCheers!", "base": "8.33", "sku": "FM28", "tags": ["wedding speech", "speech template", "wedding toast", "best man speech", "maid of honour", "father of the bride", "groom speech", "mother of the bride", "wedding speech gift", "bride speech", "editable speech", "printable speech", "uk wedding speech"], "imgs": ["bundle-main.jpg", "best-man-inside.jpg", "father-of-the-bride-tmpl.jpg"]};
const sl=ms=>new Promise(r=>setTimeout(r,ms));
for(let i=0;i<40&&!document.getElementById('listing-title-input');i++)await sl(300);
const base='https://raw.githubusercontent.com/CollingwoodCymbals/cymbalsamples/claude/project-thread-oxai21/etsy-temp/ws/';
const files=[];for(const n of L.imgs){const b=await fetch(base+n).then(r=>r.blob());files.push(new File([b],n.replace('.jpg','')+'.jpg',{type:'image/jpeg'}))}
const da=()=>[...document.querySelectorAll('button')].filter(b=>b.innerText.trim()==='Delete all');
da()[0].click();await sl(1200);da().pop().click();await sl(2000);
const inp=document.querySelector('input[type=file][name=listing-media-upload]');const dt=new DataTransfer();files.forEach(f=>dt.items.add(f));inp.files=dt.files;inp.dispatchEvent(new Event('change',{bubbles:true}));await sl(7000);
const setv=(el,v)=>{const p=el.tagName==='TEXTAREA'?HTMLTextAreaElement.prototype:HTMLInputElement.prototype;Object.getOwnPropertyDescriptor(p,'value').set.call(el,v);el.dispatchEvent(new Event('input',{bubbles:true}));el.dispatchEvent(new Event('change',{bubbles:true}));el.dispatchEvent(new Event('blur',{bubbles:true}))};
setv(document.getElementById('listing-title-input'),L.title);setv(document.getElementById('listing-description-textarea'),L.desc);setv(document.getElementById('listing-price-input'),L.base);setv(document.getElementById('listing-sku-input'),L.sku);
await sl(500);da().pop().click();await sl(1200);da().pop().click();await sl(1200);
const ti=document.getElementById('listing-tags-input');const box=ti.parentElement.parentElement.parentElement;
for(const t of L.tags){Object.getOwnPropertyDescriptor(HTMLInputElement.prototype,'value').set.call(ti,t);ti.dispatchEvent(new Event('input',{bubbles:true}));await sl(150);([...box.querySelectorAll('button')].find(b=>b.innerText.trim()==='Add')||[...document.querySelectorAll('button')].find(b=>b.innerText.trim()==='Add')).click();await sl(300)}
const t=document.body.innerText;const g=id=>document.getElementById(id)?.value;
const imgs=[...document.querySelectorAll('img')].filter(i=>i.naturalWidth===570).length;
const ok=imgs===L.imgs.length&&t.includes('All 13 used')&&L.tags.every(x=>t.includes(x))&&!t.includes('best man proposal')===(L.key!=='best-man')&&g('listing-title-input')===L.title&&g('listing-price-input')===L.base;
JSON.stringify({imgs,ok,title:g('listing-title-input').slice(0,30),price:g('listing-price-input'),sku:g('listing-sku-input')})